PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, email TEXT NOT NULL UNIQUE COLLATE NOCASE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, disabled INTEGER NOT NULL DEFAULT 0, must_change_password INTEGER NOT NULL DEFAULT 0, owner INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE departments(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE teams(id TEXT PRIMARY KEY, department_id TEXT NOT NULL REFERENCES departments(id), name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, UNIQUE(department_id,name));
CREATE TABLE memberships(user_id TEXT REFERENCES users(id), department_id TEXT REFERENCES departments(id), team_id TEXT REFERENCES teams(id), PRIMARY KEY(user_id,department_id,team_id));
CREATE TABLE roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE permissions(id TEXT PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE role_permissions(role_id TEXT REFERENCES roles(id), permission_id TEXT REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles(user_id TEXT REFERENCES users(id), role_id TEXT REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE apps(id TEXT PRIMARY KEY,name TEXT NOT NULL,redirects TEXT NOT NULL,origins TEXT NOT NULL,scopes TEXT NOT NULL,disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE consents(user_id TEXT REFERENCES users(id),app_id TEXT REFERENCES apps(id),scopes TEXT NOT NULL,PRIMARY KEY(user_id,app_id));
CREATE TABLE sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),app_id TEXT REFERENCES apps(id),kind TEXT NOT NULL,expires INTEGER NOT NULL,family TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0,scopes TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE codes(hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),app_id TEXT REFERENCES apps(id),redirect TEXT NOT NULL,challenge TEXT NOT NULL,scopes TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT,target TEXT,action TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE profile_fields(key TEXT PRIMARY KEY,label TEXT NOT NULL,type TEXT NOT NULL,options TEXT NOT NULL DEFAULT '[]',visibility TEXT NOT NULL DEFAULT 'private');
CREATE TABLE profile_values(user_id TEXT REFERENCES users(id),field_key TEXT REFERENCES profile_fields(key),value TEXT NOT NULL,PRIMARY KEY(user_id,field_key));
